def page(title, body):
    nav="".join('<a href="'+h+'">'+t+'</a>' for h,t in NAV)
    head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' - Inheritance Decision Dashboard</title><link rel="stylesheet" href="assets/style.css"></head><body>'
    hdr='<header><div class="wrap"><a class="brand" href="index.html">Inheritance Decision Dashboard</a><nav>'+nav+'</nav><p class="privacy">Anonymized: [DECEDENT] / [BENEFICIARY] / [TRUSTEE] / Property A (Cupertino 95014) / Property B (San Francisco 94122). No personal information on this site. Decision-analysis money rounded to nearest $10.</p></div></header>'
    ftr='<footer class="wrap"><p>Sources linked on <a href="sources-verification.html">Sources and Verification</a>. Unverified items blank-flagged on <a href="flagged-review.html">Flagged for Review</a>. General information, not legal/tax advice. Data: <a href="data/projections.csv">projections.csv</a> / <a href="data/sources.csv">sources.csv</a> / Model: <a href="scripts/calculate.py">calculate.py</a></p></footer></body></html>'
    return head+hdr+'<main class="wrap">'+body+'</main>'+ftr
def table(headers, data):
    h="".join("<th>"+x+"</th>" for x in headers)
    b="".join("<tr>"+"".join("<td>"+str(c)+"</td>" for c in r)+"</tr>" for r in data)
    return '<div class="tablewrap"><table><thead><tr>'+h+'</tr></thead><tbody>'+b+'</tbody></table></div>'
def note(t): return '<p class="note">'+t+'</p>'
def badge(t): return '<span class="badge">'+t+'</span>'

